// Exact integral 2048x2048 Cholesky residual checker; no floating-point decisions.
// Input is the matrix generated by WeilZetaActivePrimeSevenTenthsInputs.py.
#include <cassert>
#ifdef NDEBUG
#error "NDEBUG disables mandatory certificate assertions"
#endif
#include <cstdint>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
using i128 = __int128_t;
using i64 = std::int64_t;

static i128 abs128(i128 x) { return x < 0 ? -x : x; }
static i64 floor_div(i128 a, i64 b) {
    assert(b > 0);
    i128 q = a / b;
    if (a < 0 && a % b != 0) --q;
    assert(q >= INT64_MIN && q <= INT64_MAX);
    return static_cast<i64>(q);
}
static i64 isqrt128(i128 x) {
    assert(x >= 0);
    std::uint64_t lo = 0, hi = 1ULL << 60;
    while (lo + 1 < hi) {
        std::uint64_t mid = lo + (hi - lo) / 2;
        if (static_cast<i128>(mid) * mid <= x) lo = mid;
        else hi = mid;
    }
    assert(static_cast<i128>(lo) * lo <= x);
    assert(static_cast<i128>(lo + 1) * (lo + 1) > x);
    return static_cast<i64>(lo);
}
int main(int argc, char** argv) {
    if (argc != 2) { std::cerr << "usage: verifier <generated_integer_matrix.txt>\n"; return 2; }
    std::ifstream in(argv[1]);
    if (!in) { std::cerr << "input unavailable\n"; return 3; }
    i64 N, S, SB, OFFSET;
    in >> N >> S >> SB >> OFFSET;
    if (!(N == 2048 && S == (1LL<<30) && SB == (1LL<<30) && OFFSET == 205000)) {
       std::cerr << "incorrect matrix parameters\n"; return 4;
    }
    const i64 factor = (SB * SB) / S;
    assert(factor == 1LL<<30);
    std::vector<i64> D(N*N), B(N*N, 0);
    for (i64 i=0;i<N;i++) for(i64 j=0;j<N;j++) {
       if (!(in >> D[i*N+j])) { std::cerr << "incomplete matrix";return 5; }
    }
    std::string extra;
    if (in >> extra) {std::cerr << "unexpected extra matrix tokens\n";return 6;}
    for (i64 i=0;i<N;i++) for(i64 j=0;j<i;j++) {
       if(D[i*N+j] != D[j*N+i]) {std::cerr << "not symmetric\n";return 7;}
    }
    for (i64 i=0;i<N;i++) {
       i128 pivot = static_cast<i128>(D[i*N+i]) * factor;
       for (i64 k=0;k<i;k++) pivot -= static_cast<i128>(B[i*N+k]) * B[i*N+k];
       if (pivot<=0) {std::cerr << "nonpositive approximate pivot at "<<i<<"\n";return 8;}
       B[i*N+i] = isqrt128(pivot);
       if (B[i*N+i]==0) {std::cerr << "zero pivot at "<<i<<"\n";return 9;}
       for (i64 j=i+1;j<N;j++) {
          i128 value = static_cast<i128>(D[j*N+i])*factor;
          for (i64 k=0;k<i;k++) value-=static_cast<i128>(B[j*N+k])*B[i*N+k];
          B[j*N+i]=floor_div(value,B[i*N+i]);
       }
       if ((i+1)%256 == 0) std::cerr << "Cholesky rows " << (i+1) << "/" << N << "\n";
    }
    std::vector<i128> rows(N, 0);
    for (i64 i=0;i<N;i++) {
       for(i64 j=0;j<=i;j++) {
          i128 error = static_cast<i128>(D[i*N+j])*factor;
          for (i64 k=0;k<=j;k++) error -= static_cast<i128>(B[i*N+k])*B[j*N+k];
          i128 mag=abs128(error);
          rows[i]+=mag;
          if(i!=j)rows[j]+=mag;
       }
       if ((i+1)%256 == 0) std::cerr << "Residual rows " << (i+1) << "/" << N << "\n";
    }
    i128 worst=0;
    for(auto row:rows) if(row>worst)worst=row;
    const i128 denominator=static_cast<i128>(SB)*SB;
    const i128 marginNumerator=static_cast<i128>(OFFSET-N)*factor - worst;
    std::cerr << "diagnostic residual=" << (long double)worst/(long double)denominator << " margin=" << (long double)marginNumerator/(long double)denominator << "\n";
    if (!(worst*100000<denominator && N*500000LL<S && marginNumerator*6000>denominator)) {
       std::cerr << "FAIL exact residual/100000 or certified 1/6000 margin\n";return 10;
    }
    std::cout << "PASS: all 2048x2048 integer Cholesky pivots and complete symmetric residual rows\n";
    std::cout << "PASS: residual < 1/100000, rounding row < 1/500000, exact mean margin >1/6000\n";
    std::cout << "diagnostic residual " << static_cast<long double>(worst)/static_cast<long double>(denominator) << "\n";
    std::cout << "diagnostic spectral mean margin " << static_cast<long double>(marginNumerator)/static_cast<long double>(denominator) << "\n";
    std::cout << "No floating-point used for any assertion, witness, or sign decision\n";
}
